args.sql:
SELECT DISTINCT month_year FROM (
    SELECT SUBSTR(txn_date, 1, 7) as month_year FROM customer_transactions
) ORDER BY month_year

function.arguments:
{"sql": "WITH all_customers AS (
    SELECT DISTINCT customer_id FROM customer_transactions
),
all_months AS (
    SELECT DISTINCT SUBSTR(txn_date, 1, 7) as month_year FROM customer_transactions
),
all_combinations AS (
    SELECT c.customer_id, m.month_year
    FROM all_customers c
    CROSS JOIN all_months m
)
SELECT * FROM all_combinations ORDER BY customer_id, month_year LIMIT 20"}
